select 

from MOD_ASSET_GRADE_SPECIAL_CONFIG
where SEQNO = #{seqno,jdbcType=VARCHAR}

    select 

    from MOD_ASSET_GRADE_SPECIAL_CONFIG
    where 1=1

    	and FINPROD_ID = #{finprodId,jdbcType=VARCHAR}


     AND FINPROD_ID IN(

				#{item}

     )

with rate as( SELECT BASIS_CYY ccyOriginal, QUOT_CYY ccyConvert, TRADE_DATE publishDate, CLOSE_PRICE/(case when info.QUOT_UNIT=0 then 1 else info.QUOT_UNIT end) yeid FROM MST_EXCHARGE_QUOTE info where info.QUOT_CYY = 'CNY' and info.DATASOURCE_TYPE='SAFE' and info.TRADE_DATE = (select max(t.TRADE_DATE) from MST_EXCHARGE_QUOTE t where t.BASIS_CYY = info.BASIS_CYY and t.QUOT_CYY = info.QUOT_CYY and t.DATASOURCE_TYPE='SAFE' and t.TRADE_DATE <= #{reportDate, jdbcType = DATE}) ) select * from( select FPT.TYPE_9 assettypeTwo,FPT.TYPE_10 assettypeThree,FPT.TYPE_11 assettypeFour,FPT.TYPE_12 assettypeFive, sum((nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+nvl(DELAY_PAY_AMT,0)+nvl(TDY_LOSS_AMT,0))*nvl(rate.yeid,1)) scaleG06, sum((nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_LOSS_AMT,0))*nvl(rate.yeid,1)) scalePbc, 0 value from PTL_SEC_VALUTION psv left join FIN_PRODUCT fp on FP.FINPROD_ID=PSV.FINPROD_ID left join FIN_PRODUCT fpp on fpp.FINPROD_ID=FP.P_FINPROD_ID left join FIN_PRODUCT_TYPE fpt on FPT.FINPROD_ID=nvl(fpp.FINPROD_ID,PSV.FINPROD_ID) left join fin_product fp1 on FP1.FINPROD_MARKET_ID=psv.PORTFOLIO_ID and fp1.P_FINPROD_ID is null left join FIN_PRODUCT_ADD fpa on fpa.FINPROD_ID=fp1.FINPROD_ID left join rate on psv.CCY=rate.ccyOriginal where psv.INV_AIM!='SELL' and psv.cdate=#{reportDate, jdbcType = DATE} and psv.FINPROD_ID not in (select acct_no from stl_capacct_info) and fpt.type_9 !='12'
and fp1.PROFIT_TYPE='02' and fpa.IS_CASH_MANAGE='Y'
and fp1.PROFIT_TYPE='02' and fp1.OPERATION_TYPE='01'
and fp1.PROFIT_TYPE !='02' and fp1.OPERATION_TYPE='02' and fpa.IS_CASH_MANAGE='Y'
and fp1.PROFIT_TYPE !=02 and fp1.OPERATION_TYPE='02' and fpa.IS_CASH_MANAGE='N'
and fp1.PROFIT_TYPE !=02 and fp1.OPERATION_TYPE='01'
and (fpt.type_8 not in('F03','F04','F09') or fpt.TYPE_12 !='105')
and (fpt.type_8 not in('F03','F04','F09') and fpt.TYPE_12 !='157')
and PSV.PORTFOLIO_ID=#{prodid, jdbcType = VARCHAR}
and nvl(fpp.FINPROD_MARKET_ID,fp.FINPROD_MARKET_ID)=#{assetcode, jdbcType = VARCHAR}
#{prodid,jdbcType=VARCHAR}
#{assetcode,jdbcType=VARCHAR}
group by FPT.TYPE_9, FPT.TYPE_10, FPT.TYPE_11, FPT.TYPE_12 union all select '05' assettypeTwo,'17' assettypeThree,'024' assettypeFour,'024' assettypeFive, sum(t.dsc_cost_amt*nvl(rate.yeid,1)) scaleG06, sum(t.dsc_cost_amt*nvl(rate.yeid,1)) scalePbc, sum(t.dsc_cost_amt*nvl(rate.yeid,1)) value from ptl_sec_valution t left join rate on t.CCY=rate.ccyOriginal where t.finprod_id in (select acct_no from stl_capacct_info) and t.sec_acct_id = '999999' and t.cdate = #{reportDate, jdbcType = DATE}
#{prodid1,jdbcType=VARCHAR}
and t.PORTFOLIO_ID=#{prodid, jdbcType = VARCHAR}
having sum(t.dsc_cost_amt*nvl(rate.yeid,1)) !=0 ) where 1=1
and assettypeTwo=#{assettypeTwo, jdbcType = VARCHAR}
and assettypeThree=#{assettypeThree, jdbcType = VARCHAR}
and assettypeFour=#{assettypeFour, jdbcType = VARCHAR}
and assettypeFive=#{assettypeFive, jdbcType = VARCHAR}
order by assettypeTwo, assettypeThree, assettypeFour, assettypeFive

select assettypeTwo,assettypeThree,assettypeFour,assettypeFive,days ,sum(scalePbc) noFixedTerm from (select FPT.TYPE_9 assettypeTwo,FPT.TYPE_10 assettypeThree,FPT.TYPE_11 assettypeFour,FPT.TYPE_12 assettypeFive, case when nvl(bsbad.end_days,0)<=0 then '01' when nvl(bsbad.end_days,0)>0 and nvl(bsbad.end_days,0)<=30 then '02' when nvl(bsbad.end_days,0)>30 and nvl(bsbad.end_days,0)<=90 then '03' when nvl(bsbad.end_days,0)>90 and nvl(bsbad.end_days,0)<=180 then '04' when nvl(bsbad.end_days,0)>180 and nvl(bsbad.end_days,0)<=360 then '05' when nvl(bsbad.end_days,0)>360 and nvl(bsbad.end_days,0)<=720 then '06' when nvl(bsbad.end_days,0)>720 and nvl(bsbad.end_days,0)<=1080 then '07' when nvl(bsbad.end_days,0)>1080 then '08' end days,
nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_LOSS_AMT,0) scalePbc from PTL_SEC_VALUTION psv left join FIN_PRODUCT fp on FP.FINPROD_ID=PSV.FINPROD_ID left join FIN_PRODUCT fpp on fpp.FINPROD_ID=FP.P_FINPROD_ID left join FIN_PRODUCT_TYPE fpt on FPT.FINPROD_ID=nvl(fpp.FINPROD_ID,PSV.FINPROD_ID) left join fin_product fp1 on FP1.FINPROD_MARKET_ID=psv.PORTFOLIO_ID and fp1.P_FINPROD_ID is null left join FIN_PRODUCT_ADD fpa on fpa.FINPROD_ID=fp1.FINPROD_ID left join BUSI_REPORT_BASIS_ASSET_DATA bsbad on BSBAD.FINPROD_ID=nvl(fpp.FINPROD_ID,PSV.FINPROD_ID) and BSBAD.PORTFOLIO_ID=PSV.PORTFOLIO_ID and BSBAD.CDATE=PSV.CDATE and BSBAD.INV_AIM=PSV.INV_AIM where psv.INV_AIM!='SELL' and fpt.type_9 !='12' and psv.cdate=#{reportDate, jdbcType = DATE} and psv.FINPROD_ID not in (select acct_no from stl_capacct_info)
and fp1.PROFIT_TYPE='02' and fpa.IS_CASH_MANAGE='Y'
and fp1.PROFIT_TYPE='02' and fp1.OPERATION_TYPE='01'
and fp1.PROFIT_TYPE !='02' and fp1.OPERATION_TYPE='02' and fpa.IS_CASH_MANAGE='Y'
and fp1.PROFIT_TYPE !=02 and fp1.OPERATION_TYPE='02' and fpa.IS_CASH_MANAGE='N'
and fp1.PROFIT_TYPE !=02 and fp1.OPERATION_TYPE='01'
and (fpt.type_8 not in('F03','F04','F09') or fpt.TYPE_12 !='105')
and (fpt.type_8 not in('F03','F04','F09') and fpt.TYPE_12 !='157')
and PSV.PORTFOLIO_ID=#{prodid, jdbcType = VARCHAR}
and nvl(fpp.FINPROD_MARKET_ID,fp.FINPROD_MARKET_ID)=#{assetcode, jdbcType = VARCHAR}
#{prodid,jdbcType=VARCHAR}
#{assetcode,jdbcType=VARCHAR}
) where days=#{days,jdbcType=VARCHAR} group by assettypeTwo,assettypeThree,assettypeFour,assettypeFive,days

select psv.FINPROD_MARKET_ID assetcode,PSV.SHARE_AMT shareamt
from BUSI_REPORT_BASIS_ASSET_DATA psv
left join FIN_PRODUCT fp on FP.FINPROD_ID=PSV.FINPROD_ID
left join FIN_PRODUCT fpp on fpp.FINPROD_ID=FP.P_FINPROD_ID
left join FIN_PRODUCT_TYPE fpt
on FPT.FINPROD_ID=nvl(fpp.FINPROD_ID,PSV.FINPROD_ID)
left join fin_product fp1
on FP1.FINPROD_MARKET_ID=psv.PORTFOLIO_ID
and fp1.P_FINPROD_ID is null
left join FIN_PRODUCT_ADD fpa
on fpa.FINPROD_ID=fp1.FINPROD_ID
where cdate=#{reportDate, jdbcType = DATE}

  and fp1.PROFIT_TYPE='02' and fpa.IS_CASH_MANAGE='Y'


  and fp1.PROFIT_TYPE='02' and fp1.OPERATION_TYPE='01'


  and fp1.PROFIT_TYPE !='02' and fp1.OPERATION_TYPE='02' and fpa.IS_CASH_MANAGE='Y'


  and fp1.PROFIT_TYPE !=02 and fp1.OPERATION_TYPE='02' and fpa.IS_CASH_MANAGE='N'


  and fp1.PROFIT_TYPE !=02 and fp1.OPERATION_TYPE='01'


  and (fpt.type_8 in('F03','F04','F09') and fpt.TYPE_12 ='105')


  and (fpt.type_8  in('F03','F04','F09') or fpt.TYPE_12 ='157')


  and PSV.PORTFOLIO_ID=#{prodid, jdbcType = VARCHAR}


  and nvl(fpp.FINPROD_MARKET_ID,fp.FINPROD_MARKET_ID)=#{assetcode, jdbcType = VARCHAR}



    #{prodid,jdbcType=VARCHAR}




    #{assetcode,jdbcType=VARCHAR}



  and FPT.TYPE_9=#{assettypeTwo, jdbcType = VARCHAR}


  and FPT.TYPE_10=#{assettypeThree, jdbcType = VARCHAR}


  and FPT.TYPE_11=#{assettypeFour, jdbcType = VARCHAR}


  and FPT.TYPE_12=#{assettypeFive, jdbcType = VARCHAR}

select FPT.TYPE_9 assettypeTwo,FPT.TYPE_10 assettypeThree,FPT.TYPE_11 assettypeFour,FPT.TYPE_12 assettypeFive, sum (decode(psv.FINPROD_TYPE2, 'F11',psv.INT_PRIN_AMT, 'F12',psv.INT_PRIN_AMT, 'F13',psv.INT_PRIN_AMT, 'F14',psv.INT_PRIN_AMT, 'F29',psv.INT_PRIN_AMT, 'F30',psv.INT_PRIN_AMT, decode(psv.FINPROD_TYPE2,'F01',psv.INT_PRIN_AMT*psv.SHARE_AMT,psv.INT_PRIN_AMT*psv.SHARE_AMT/100))) value from BUSI_REPORT_BASIS_ASSET_DATA psv left join FIN_PRODUCT fp on FP.FINPROD_ID=PSV.FINPROD_ID left join FIN_PRODUCT fpp on fpp.FINPROD_ID=FP.P_FINPROD_ID left join FIN_PRODUCT_TYPE fpt on FPT.FINPROD_ID=PSV.FINPROD_ID left join fin_product fp1 on FP1.FINPROD_MARKET_ID=psv.PORTFOLIO_ID and fp1.P_FINPROD_ID is null left join FIN_PRODUCT_ADD fpa on fpa.FINPROD_ID=fp1.FINPROD_ID where psv.INV_AIM!='SELL' and psv.cdate=#{reportDate, jdbcType = DATE} and psv.FINPROD_ID not in (select acct_no from stl_capacct_info) and fpt.type_9 !='12'
and fp1.PROFIT_TYPE='02' and fpa.IS_CASH_MANAGE='Y'
and fp1.PROFIT_TYPE='02' and fp1.OPERATION_TYPE='01'
and fp1.PROFIT_TYPE !='02' and fp1.OPERATION_TYPE='02' and fpa.IS_CASH_MANAGE='Y'
and fp1.PROFIT_TYPE !=02 and fp1.OPERATION_TYPE='02' and fpa.IS_CASH_MANAGE='N'
and fp1.PROFIT_TYPE !=02 and fp1.OPERATION_TYPE='01'
and (fpt.type_8 not in('F03','F04','F09') or fpt.TYPE_12 !='105')
and (fpt.type_8 not in('F03','F04','F09') and fpt.TYPE_12 !='157')
and FPT.TYPE_9=#{assettypeTwo, jdbcType = VARCHAR}
and FPT.TYPE_10=#{assettypeThree, jdbcType = VARCHAR}
and FPT.TYPE_11=#{assettypeFour, jdbcType = VARCHAR}
and FPT.TYPE_12=#{assettypeFive, jdbcType = VARCHAR}
and PSV.PORTFOLIO_ID=#{prodid, jdbcType = VARCHAR}
and nvl(fpp.FINPROD_MARKET_ID,fp.FINPROD_MARKET_ID)=#{assetcode, jdbcType = VARCHAR}
#{prodid,jdbcType=VARCHAR}
#{assetcode,jdbcType=VARCHAR}
group by FPT.TYPE_9, FPT.TYPE_10, FPT.TYPE_11, FPT.TYPE_12

select FPT.TYPE_9 assettypeTwo,FPT.TYPE_10 assettypeThree,FPT.TYPE_11 assettypeFour,FPT.TYPE_12 assettypeFive, sum(decode(psv.FINPROD_TYPE2, 'F11',psv.INT_PRIN_AMT, 'F12',psv.INT_PRIN_AMT, 'F13',psv.INT_PRIN_AMT, 'F14',psv.INT_PRIN_AMT, 'F29',psv.INT_PRIN_AMT, 'F30',psv.INT_PRIN_AMT, decode(psv.FINPROD_TYPE2,'F01',psv.INT_PRIN_AMT*psv.SHARE_AMT,psv.INT_PRIN_AMT*psv.SHARE_AMT/100))*M_DURATION)/ sum(decode(psv.FINPROD_TYPE2, 'F11',psv.INT_PRIN_AMT, 'F12',psv.INT_PRIN_AMT, 'F13',psv.INT_PRIN_AMT, 'F14',psv.INT_PRIN_AMT, 'F29',psv.INT_PRIN_AMT, 'F30',psv.INT_PRIN_AMT, decode(psv.FINPROD_TYPE2,'F01',psv.INT_PRIN_AMT*psv.SHARE_AMT,psv.INT_PRIN_AMT*psv.SHARE_AMT/100))) avgDuration from BUSI_REPORT_BASIS_ASSET_DATA psv left join FIN_PRODUCT fp on FP.FINPROD_ID=PSV.FINPROD_ID left join FIN_PRODUCT fpp on fpp.FINPROD_ID=FP.P_FINPROD_ID left join FIN_PRODUCT_TYPE fpt on FPT.FINPROD_ID=PSV.FINPROD_ID left join fin_product fp1 on FP1.FINPROD_MARKET_ID=psv.PORTFOLIO_ID and fp1.P_FINPROD_ID is null left join FIN_PRODUCT_ADD fpa on fpa.FINPROD_ID=fp1.FINPROD_ID where M_DURATION is not null and fpt.type_9 !='12' and psv.INV_AIM!='SELL' and psv.FINPROD_ID not in (select acct_no from stl_capacct_info) and psv.cdate=#{reportDate, jdbcType = DATE} and FPT.TYPE_10 not in ('01','02','03','06')
and fp1.PROFIT_TYPE='02' and fpa.IS_CASH_MANAGE='Y'
and fp1.PROFIT_TYPE='02' and fp1.OPERATION_TYPE='01'
and fp1.PROFIT_TYPE !='02' and fp1.OPERATION_TYPE='02' and fpa.IS_CASH_MANAGE='Y'
and fp1.PROFIT_TYPE !=02 and fp1.OPERATION_TYPE='02' and fpa.IS_CASH_MANAGE='N'
and fp1.PROFIT_TYPE !=02 and fp1.OPERATION_TYPE='01'
and (fpt.type_8 not in('F03','F04','F09') or fpt.TYPE_12 !='105')
and (fpt.type_8 not in('F03','F04','F09') and fpt.TYPE_12 !='157')
and PSV.PORTFOLIO_ID=#{prodid, jdbcType = VARCHAR}
and nvl(fpp.FINPROD_MARKET_ID,fp.FINPROD_MARKET_ID)=#{assetcode, jdbcType = VARCHAR}
#{prodid,jdbcType=VARCHAR}
#{assetcode,jdbcType=VARCHAR}
and FPT.TYPE_9=#{assettypeTwo, jdbcType = VARCHAR}
and FPT.TYPE_10=#{assettypeThree, jdbcType = VARCHAR}
and FPT.TYPE_11=#{assettypeFour, jdbcType = VARCHAR}
and FPT.TYPE_12=#{assettypeFive, jdbcType = VARCHAR}
group by FPT.TYPE_9, FPT.TYPE_10, FPT.TYPE_11, FPT.TYPE_12 HAVING sum(decode(psv.FINPROD_TYPE2, 'F11',psv.INT_PRIN_AMT, 'F12',psv.INT_PRIN_AMT, 'F13',psv.INT_PRIN_AMT, 'F14',psv.INT_PRIN_AMT, 'F29',psv.INT_PRIN_AMT, 'F30',psv.INT_PRIN_AMT, decode(psv.FINPROD_TYPE2,'F01',psv.INT_PRIN_AMT*psv.SHARE_AMT,psv.INT_PRIN_AMT*psv.SHARE_AMT/100))) !=0

select FPT.TYPE_9 assettypeTwo,FPT.TYPE_10 assettypeThree,FPT.TYPE_11 assettypeFour,FPT.TYPE_12 assettypeFive, sum(decode(psv.FINPROD_TYPE2, 'F11',psv.INT_PRIN_AMT, 'F12',psv.INT_PRIN_AMT, 'F13',psv.INT_PRIN_AMT, 'F14',psv.INT_PRIN_AMT, 'F29',psv.INT_PRIN_AMT, 'F30',psv.INT_PRIN_AMT, decode(psv.FINPROD_TYPE2,'F01',psv.INT_PRIN_AMT*psv.SHARE_AMT,psv.INT_PRIN_AMT*psv.SHARE_AMT/100))*MYIELD)/ sum(decode(psv.FINPROD_TYPE2, 'F11',psv.INT_PRIN_AMT, 'F12',psv.INT_PRIN_AMT, 'F13',psv.INT_PRIN_AMT, 'F14',psv.INT_PRIN_AMT, 'F29',psv.INT_PRIN_AMT, 'F30',psv.INT_PRIN_AMT, decode(psv.FINPROD_TYPE2,'F01',psv.INT_PRIN_AMT*psv.SHARE_AMT,psv.INT_PRIN_AMT*psv.SHARE_AMT/100))) avgMyield from BUSI_REPORT_BASIS_ASSET_DATA psv left join FIN_PRODUCT fp on FP.FINPROD_ID=PSV.FINPROD_ID left join FIN_PRODUCT fpp on fpp.FINPROD_ID=FP.P_FINPROD_ID left join FIN_PRODUCT_TYPE fpt on FPT.FINPROD_ID=PSV.FINPROD_ID left join fin_product fp1 on FP1.FINPROD_MARKET_ID=psv.PORTFOLIO_ID and fp1.P_FINPROD_ID is null left join FIN_PRODUCT_ADD fpa on fpa.FINPROD_ID=fp1.FINPROD_ID where MYIELD is not null and fpt.type_9 !='12' and psv.INV_AIM!='SELL' and psv.FINPROD_ID not in (select acct_no from stl_capacct_info) and psv.cdate=#{reportDate, jdbcType = DATE}
and fp1.PROFIT_TYPE='02' and fpa.IS_CASH_MANAGE='Y'
and fp1.PROFIT_TYPE='02' and fp1.OPERATION_TYPE='01'
and fp1.PROFIT_TYPE !='02' and fp1.OPERATION_TYPE='02' and fpa.IS_CASH_MANAGE='Y'
and fp1.PROFIT_TYPE !=02 and fp1.OPERATION_TYPE='02' and fpa.IS_CASH_MANAGE='N'
and fp1.PROFIT_TYPE !=02 and fp1.OPERATION_TYPE='01'
and (fpt.type_8 not in('F03','F04','F09') or fpt.TYPE_12 !='105')
and (fpt.type_8 not in('F03','F04','F09') and fpt.TYPE_12 !='157')
and PSV.PORTFOLIO_ID=#{prodid, jdbcType = VARCHAR}
and nvl(fpp.FINPROD_MARKET_ID,fp.FINPROD_MARKET_ID)=#{assetcode, jdbcType = VARCHAR}
#{prodid,jdbcType=VARCHAR}
#{assetcode,jdbcType=VARCHAR}
and FPT.TYPE_9=#{assettypeTwo, jdbcType = VARCHAR}
and FPT.TYPE_10=#{assettypeThree, jdbcType = VARCHAR}
and FPT.TYPE_11=#{assettypeFour, jdbcType = VARCHAR}
and FPT.TYPE_12=#{assettypeFive, jdbcType = VARCHAR}
group by FPT.TYPE_9, FPT.TYPE_10, FPT.TYPE_11, FPT.TYPE_12 HAVING sum(decode(psv.FINPROD_TYPE2, 'F11',psv.INT_PRIN_AMT, 'F12',psv.INT_PRIN_AMT, 'F13',psv.INT_PRIN_AMT, 'F14',psv.INT_PRIN_AMT, 'F29',psv.INT_PRIN_AMT, 'F30',psv.INT_PRIN_AMT, decode(psv.FINPROD_TYPE2,'F01',psv.INT_PRIN_AMT*psv.SHARE_AMT,psv.INT_PRIN_AMT*psv.SHARE_AMT/100))) !=0 order by FPT.TYPE_9, FPT.TYPE_10, FPT.TYPE_11,FPT.TYPE_12

    	select val_date querydate,smv shareamt from
