with rate as( SELECT BASIS_CYY ccyOriginal, QUOT_CYY ccyConvert, TRADE_DATE publishDate, CLOSE_PRICE/(case when info.QUOT_UNIT=0 then 1 else info.QUOT_UNIT end) yeid FROM MST_EXCHARGE_QUOTE info where info.QUOT_CYY = 'CNY' and info.DATASOURCE_TYPE='SAFE' and info.TRADE_DATE = (select max(t.TRADE_DATE) from MST_EXCHARGE_QUOTE t where t.BASIS_CYY = info.BASIS_CYY and t.QUOT_CYY = info.QUOT_CYY and t.DATASOURCE_TYPE='SAFE' and t.TRADE_DATE <= #{reportDate, jdbcType = DATE}) ) select FPT.TYPE_9 assettypeTwo,FPT.TYPE_10 assettypeThree,FPT.TYPE_11 assettypeFour,FPT.TYPE_12 assettypeFive, sum(nvl(smv,0)*nvl(rate.yeid,1)) shareamt,FP.FINPROD_MARKET_ID assetcode from rsk_valtbl_asset_sub rvas left join FIN_PRODUCT fp on FP.FINPROD_ID=rvas.FINPROD_ID left join FIN_PRODUCT_TYPE fpt on FPT.FINPROD_ID=rvas.FINPROD_ID left join rate on fp.CCY=rate.ccyOriginal where RVAS.FINPROD_ID is not null and fpt.type_9 !='12' and RVAS.PTL_ID=#{assetcode, jdbcType = VARCHAR} and RVAS.VAL_DATE=#{reportDate, jdbcType = DATE}
and FPT.TYPE_9=#{assettypeTwo, jdbcType = VARCHAR}
and FPT.TYPE_10=#{assettypeThree, jdbcType = VARCHAR}
and FPT.TYPE_11=#{assettypeFour, jdbcType = VARCHAR}
and FPT.TYPE_12=#{assettypeFive, jdbcType = VARCHAR}
group by FPT.TYPE_9, FPT.TYPE_10, FPT.TYPE_11, FPT.TYPE_12, FP.FINPROD_MARKET_ID union all select '05' assettypeTwo,'17' assettypeThree,'024' assettypeFour,'024' assettypeFive, sum(nvl(smv,0)*nvl(rc.yeid,1)) shareamt, 'CASHSURPLUS' assetcode from rsk_valtbl_asset_sub rvas left join ( select yeid from rate where rate.ccyOriginal=(select ccy from FIN_PRODUCT where FINPROD_MARKET_ID='ZZGL201902010102') ) rc on 1=1 where SUB_CODE IN ('10020101','1031','1021') and RVAS.PTL_ID=#{assetcode, jdbcType = VARCHAR} and RVAS.VAL_DATE=#{reportDate, jdbcType = DATE}
and '05'=#{assettypeTwo, jdbcType = VARCHAR}
and '17'=#{assettypeThree, jdbcType = VARCHAR}
and '024'=#{assettypeFour, jdbcType = VARCHAR}
and '024'=#{assettypeFive, jdbcType = VARCHAR}
having sum(nvl(smv,0)) !=0

select FPT.TYPE_9 assettypeTwo,FPT.TYPE_10 assettypeThree,FPT.TYPE_11 assettypeFour,FPT.TYPE_12 assettypeFive, sum(decode(psv.FINPROD_TYPE2, 'F11',psv.INT_PRIN_AMT, 'F12',psv.INT_PRIN_AMT, 'F13',psv.INT_PRIN_AMT, 'F14',psv.INT_PRIN_AMT, 'F29',psv.INT_PRIN_AMT, 'F30',psv.INT_PRIN_AMT, decode(psv.FINPROD_TYPE2,'F01',psv.INT_PRIN_AMT*psv.SHARE_AMT,psv.INT_PRIN_AMT*psv.SHARE_AMT/100))*YIELD)/ sum(decode(psv.FINPROD_TYPE2, 'F11',psv.INT_PRIN_AMT, 'F12',psv.INT_PRIN_AMT, 'F13',psv.INT_PRIN_AMT, 'F14',psv.INT_PRIN_AMT, 'F29',psv.INT_PRIN_AMT, 'F30',psv.INT_PRIN_AMT, decode(psv.FINPROD_TYPE2,'F01',psv.INT_PRIN_AMT*psv.SHARE_AMT,psv.INT_PRIN_AMT*psv.SHARE_AMT/100))) avgYield from BUSI_REPORT_BASIS_ASSET_DATA psv left join FIN_PRODUCT fp on FP.FINPROD_ID=PSV.FINPROD_ID left join FIN_PRODUCT fpp on fpp.FINPROD_ID=FP.P_FINPROD_ID left join FIN_PRODUCT_TYPE fpt on FPT.FINPROD_ID=PSV.FINPROD_ID left join fin_product fp1 on FP1.FINPROD_MARKET_ID=psv.PORTFOLIO_ID and fp1.P_FINPROD_ID is null left join FIN_PRODUCT_ADD fpa on fpa.FINPROD_ID=fp1.FINPROD_ID where YIELD is not null and fpt.type_9 !='12' and psv.INV_AIM!='SELL' and psv.FINPROD_ID not in (select acct_no from stl_capacct_info) and psv.cdate=#{reportDate, jdbcType = DATE}
and fp1.PROFIT_TYPE='02' and fpa.IS_CASH_MANAGE='Y'
and fp1.PROFIT_TYPE='02' and fp1.OPERATION_TYPE='01'
and fp1.PROFIT_TYPE !='02' and fp1.OPERATION_TYPE='02' and fpa.IS_CASH_MANAGE='Y'
